// @bun
// src/token-manager.ts
function getByPath(obj, path) {
  const keys = path.split(".");
  let current = obj;
  for (const key of keys) {
    if (current == null || typeof current !== "object") {
      throw new Error(`Token path "${path}" not found in response`);
    }
    current = current[key];
  }
  if (typeof current !== "string") {
    throw new Error(`Token at path "${path}" is not a string, got: ${typeof current}`);
  }
  return current;
}

class TokenManager {
  config = null;
  token = "";
  timer = null;
  fetching = false;
  log;
  constructor(log) {
    this.log = log;
    const url = process.env.NBCB_TOKEN_URL ?? "";
    if (!url) {
      this.log.warn("NBCB_TOKEN_URL not set, token refresh disabled");
      return;
    }
    let headers = {};
    const rawHeaders = process.env.NBCB_TOKEN_HEADERS;
    if (rawHeaders) {
      try {
        headers = JSON.parse(rawHeaders);
      } catch {
        this.log.error("NBCB_TOKEN_HEADERS is not valid JSON, ignoring");
      }
    }
    this.config = {
      url,
      method: process.env.NBCB_TOKEN_METHOD?.toUpperCase() ?? "POST",
      headers,
      body: process.env.NBCB_TOKEN_BODY,
      tokenPath: process.env.NBCB_TOKEN_PATH ?? "token",
      refreshIntervalSecs: parseInt(process.env.NBCB_TOKEN_REFRESH_SECS ?? "3600", 10)
    };
  }
  get enabled() {
    return this.config !== null;
  }
  getToken() {
    return this.token;
  }
  async refreshToken() {
    if (!this.config)
      return;
    if (this.fetching)
      return;
    this.fetching = true;
    try {
      const init = {
        method: this.config.method,
        headers: {
          "Content-Type": "application/json",
          ...this.config.headers
        }
      };
      if (this.config.method === "POST" && this.config.body) {
        init.body = this.config.body;
      }
      const response = await fetch(this.config.url, init);
      if (!response.ok) {
        throw new Error(`Token request failed: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      this.token = getByPath(data, this.config.tokenPath);
      this.log.info("Token refreshed successfully");
    } catch (err) {
      this.log.error(`Failed to refresh token: ${err}`);
    } finally {
      this.fetching = false;
    }
  }
  async start() {
    if (!this.config)
      return;
    await this.refreshToken();
    const intervalMs = this.config.refreshIntervalSecs * 1000;
    this.timer = setInterval(() => {
      this.refreshToken().catch((err) => {
        this.log.error(`Periodic token refresh error: ${err}`);
      });
    }, intervalMs);
    this.log.info(`Token refresh scheduled every ${this.config.refreshIntervalSecs}s`);
  }
  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

// src/index.ts
var PROVIDER_ID = process.env.NBCB_PROVIDER_ID ?? "nbcb";
var PROVIDER_NAME = process.env.NBCB_PROVIDER_NAME ?? "NBCB";
var PROVIDER_BASE_URL = process.env.NBCB_PROVIDER_BASE_URL ?? "";
var PROVIDER_NPM = process.env.NBCB_PROVIDER_NPM ?? "@ai-sdk/openai-compatible";
var HEADER_NAME = process.env.NBCB_HEADER_NAME ?? "Authorization";
var HEADER_FORMAT = process.env.NBCB_HEADER_FORMAT ?? "Bearer {token}";
var USER_AGENT = process.env.NBCB_USER_AGENT ?? "";
var COMPAT_PROVIDER_ID_ACCESS = process.env.COMPAT_PROVIDER_ID_ACCESS ?? "auto";
function getProviderId(provider) {
  if (COMPAT_PROVIDER_ID_ACCESS === "direct") {
    return provider?.id;
  }
  if (COMPAT_PROVIDER_ID_ACCESS === "context") {
    return provider?.info?.id;
  }
  return provider?.info?.id ?? provider?.id;
}
function parseModels() {
  const raw = process.env.NBCB_PROVIDER_MODELS;
  if (!raw) {
    return {
      default: {
        name: "Default Model"
      }
    };
  }
  try {
    return JSON.parse(raw);
  } catch {
    console.error("[nbcb-provider] Failed to parse NBCB_PROVIDER_MODELS, using default");
    return { default: { name: "Default Model" } };
  }
}
var NBCBProviderPlugin = async ({ client }) => {
  const log = {
    info: (msg) => client.app.log({ body: { service: "nbcb-provider", level: "info", message: msg } }),
    warn: (msg) => client.app.log({ body: { service: "nbcb-provider", level: "warn", message: msg } }),
    error: (msg) => client.app.log({ body: { service: "nbcb-provider", level: "error", message: msg } })
  };
  const tokenManager = new TokenManager(log);
  if (tokenManager.enabled) {
    await tokenManager.start();
  }
  return {
    config: async (config) => {
      if (!PROVIDER_BASE_URL) {
        await log.warn("NBCB_PROVIDER_BASE_URL not set, skipping provider registration");
        return;
      }
      const providers = config.provider ?? {};
      providers[PROVIDER_ID] = {
        npm: PROVIDER_NPM,
        name: PROVIDER_NAME,
        options: {
          baseURL: PROVIDER_BASE_URL
        },
        models: parseModels()
      };
      config.provider = providers;
      await log.info(`Registered provider "${PROVIDER_ID}" with base URL: ${PROVIDER_BASE_URL}`);
    },
    "chat.headers": async (input, output) => {
      if (getProviderId(input.provider) !== PROVIDER_ID)
        return;
      const token = tokenManager.getToken();
      if (token) {
        output.headers[HEADER_NAME] = HEADER_FORMAT.replace("{token}", token);
      }
      if (USER_AGENT) {
        output.headers["User-Agent"] = USER_AGENT;
      }
    }
  };
};
var src_default = NBCBProviderPlugin;
export {
  src_default as default,
  NBCBProviderPlugin
};
